create table if not exists public."usuarios" (
  "id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "nombres" text NOT NULL,
  "apellidos" text NOT NULL,
  "dni" character varying(9) NOT NULL,
  "usuario" text,
  "password" text,
  "telefono" character varying(9),
  "rol" text NOT NULL,
  "tienda_id" integer,
  "estado" text DEFAULT 'activo'::text NOT NULL,
  "fecha_creacion" timestamp with time zone DEFAULT now() NOT NULL,
  "fecha_ingreso" date DEFAULT CURRENT_DATE NOT NULL,
  "fecha_salida" date,
  "fecha_nacimiento" date,
  "sueldo" numeric(12,2),
  "rol_personal" text DEFAULT 'otros'::text NOT NULL,
  "sexo" text DEFAULT 'no_especificado'::text NOT NULL,
  "telefono_emergencia" character varying(9),
  "distrito" text,
  "direccion" text,
  "grado_academico" text DEFAULT 'sin_especificar'::text NOT NULL,
  "ciclo_semestre" text,
  "estado_civil" text DEFAULT 'sin_especificar'::text NOT NULL,
  "numero_hijos" integer DEFAULT 0 NOT NULL,
  "talla_zapatillas" character varying(10),
  "talla_polo" text DEFAULT 'sin_especificar'::text NOT NULL,
  "alergia" text,
  "condicion_salud" text,
  "email" text,
  "contacto_emergencia" text,
  "motivo_salida" text,
  "tipo_documento" text DEFAULT 'dni'::text NOT NULL,
  "regimen_jornada" text,
  "tipo_turno" text,
  "tiene_parentesco" boolean DEFAULT false NOT NULL,
  "tipo_parentesco" text,
  "familiar_vinculo" text,
  "nacionalidad" text,
  "area_laboral" text,
  "carrera" text,
  "zonal_creador_id" bigint,
  "mes_cumpleanos" character(2),
  "acceso_todas_tiendas" boolean DEFAULT false NOT NULL,
  CONSTRAINT "usuarios_documento_formato_check" CHECK (tipo_documento = 'dni'::text AND dni::text ~ '^[0-9]{8}$'::text OR tipo_documento = 'ce'::text AND dni::text ~ '^[0-9]{9}$'::text),
  CONSTRAINT "usuarios_estado_check" CHECK (estado = ANY (ARRAY['activo'::text, 'inactivo'::text])),
  CONSTRAINT "usuarios_estado_civil_check" CHECK (estado_civil = ANY (ARRAY['sin_especificar'::text, 'soltero'::text, 'casado'::text, 'conviviente'::text, 'divorciado'::text, 'viudo'::text])),
  CONSTRAINT "usuarios_fecha_nacimiento_check" CHECK (fecha_nacimiento IS NULL OR fecha_nacimiento <= CURRENT_DATE),
  CONSTRAINT "usuarios_fechas_laborales_check" CHECK (fecha_salida IS NULL OR fecha_salida >= fecha_ingreso),
  CONSTRAINT "usuarios_grado_academico_check" CHECK (grado_academico = ANY (ARRAY['sin_especificar'::text, 'primaria'::text, 'secundaria'::text, 'tecnico'::text, 'universitario'::text, 'postgrado'::text])),
  CONSTRAINT "usuarios_mes_cumpleanos_check" CHECK (mes_cumpleanos IS NULL OR mes_cumpleanos ~ '^(0[1-9]|1[0-2])$'::text),
  CONSTRAINT "usuarios_numero_hijos_check" CHECK (numero_hijos >= 0),
  CONSTRAINT "usuarios_parentesco_detalle_check" CHECK (tiene_parentesco = false OR btrim(COALESCE(tipo_parentesco, ''::text)) <> ''::text AND btrim(COALESCE(familiar_vinculo, ''::text)) <> ''::text),
  CONSTRAINT "usuarios_pkey" PRIMARY KEY (id),
  CONSTRAINT "usuarios_regimen_jornada_check" CHECK (regimen_jornada IS NULL OR (regimen_jornada = ANY (ARRAY['4h'::text, '8h'::text, '12h'::text]))),
  CONSTRAINT "usuarios_rol_personal_check" CHECK (rol_personal = ANY (ARRAY['administrador'::text, 'operante'::text, 'lider_equipo'::text, 'otros'::text])),
  CONSTRAINT "usuarios_sexo_check" CHECK (sexo = ANY (ARRAY['hombre'::text, 'mujer'::text, 'no_especificado'::text])),
  CONSTRAINT "usuarios_sueldo_check" CHECK (sueldo IS NULL OR sueldo >= 0::numeric),
  CONSTRAINT "usuarios_talla_polo_check" CHECK (talla_polo = ANY (ARRAY['sin_especificar'::text, 's'::text, 'm'::text, 'l'::text, 'xl'::text, 'xxl'::text])),
  CONSTRAINT "usuarios_telefono_emergencia_check" CHECK (telefono_emergencia IS NULL OR telefono_emergencia::text ~ '^[0-9]{9}$'::text),
  CONSTRAINT "usuarios_tienda_rol_check" CHECK ((rol = ANY (ARRAY['gerencia_general'::text, 'gerente_comercial'::text, 'marketing'::text, 'coach'::text, 'jefe_zonal'::text])) AND tienda_id IS NULL OR (rol = ANY (ARRAY['jefe_tienda'::text, 'asistente_tienda'::text, 'jefe_seguridad'::text, 'jefe_area'::text, 'seguridad'::text, 'caja'::text, 'almacenero'::text, 'vendedor'::text, 'asistente'::text, 'trabajador'::text])) AND tienda_id IS NOT NULL),
  CONSTRAINT "usuarios_tipo_documento_check" CHECK (tipo_documento = ANY (ARRAY['dni'::text, 'ce'::text])),
  CONSTRAINT "usuarios_tipo_turno_check" CHECK (tipo_turno IS NULL OR (tipo_turno = ANY (ARRAY['apertura'::text, 'intermedio'::text, 'cierre'::text, 'part_time'::text])))
);

comment on column public."usuarios"."grado_academico" is 'Nivel de estudio del trabajador.';
comment on column public."usuarios"."contacto_emergencia" is 'Nombres y apellidos del contacto de emergencia.';
comment on column public."usuarios"."motivo_salida" is 'Motivo registrado al finalizar la relación laboral.';

create table if not exists public."validaciones_marketing" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "campana_id" bigint,
  "descripcion" text NOT NULL,
  "presupuesto" numeric(14,2) NOT NULL,
  "estado" text DEFAULT 'pendiente'::text NOT NULL,
  "registrado_por" integer NOT NULL,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "nombre" text,
  CONSTRAINT "validaciones_marketing_estado_check" CHECK (estado = ANY (ARRAY['pendiente'::text, 'aprobada'::text, 'cancelada'::text, 'observada'::text, 'rechazada'::text])),
  CONSTRAINT "validaciones_marketing_pkey" PRIMARY KEY (id),
  CONSTRAINT "validaciones_marketing_presupuesto_check" CHECK (presupuesto >= 0::numeric)
);

create table if not exists public."visitas_zonales" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "tienda_id" bigint NOT NULL,
  "jefe_zonal_id" bigint,
  "fecha" date NOT NULL,
  "periodo" text,
  "puntaje" numeric(5,2),
  "checklist_path" text,
  "checklist_nombre" text,
  "observacion_general" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  CONSTRAINT "visitas_zonales_pkey" PRIMARY KEY (id),
  CONSTRAINT "visitas_zonales_puntaje_check" CHECK (puntaje IS NULL OR puntaje >= 0::numeric AND puntaje <= 100::numeric)
);

